    return A

def count_positive_eigenvalues(A: List[List[float]]) -> int:
    n = len(A)
    eigenvalues = [0] * n
    for i in range(n):
        if abs(A[i][i]) > 1e-9:
            eigenvalues[i] = A[i][i]
    return sum(1 for ev in eigenvalues if ev > 0)

def max_cut_instance(n: int) -> List[List[int]]:
